//! The app's icons. Most are Phosphor's regular and fill weights, on Phosphor's 256 grid
//! (https://phosphoricons.com, MIT, see licenses/PHOSPHOR-MIT.txt); the comment after each names
//! the Phosphor glyph. The ones on a 24 grid were drawn for Glint, in a stroke that matches.
//! The player keeps its own glyphs (`np_icons.rs`).

use rune::Icon;

macro_rules! icons {
    ($($name:ident($view:literal) => $body:literal;)*) => {
        $( pub static $name: Icon = Icon { name: concat!("icon-", stringify!($name)), view: $view as f32, body: $body }; )*
    };
}

